/// <summary>
/// PricingAttribute of table <c>RetailLoyaltyCard</c> field LoyaltyEnrollmentDateLocal.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::SalesTable, GUPPricingAttributeSourceLevel::Header)]
internal class GUPPricingAttributeRetailLoyaltyCardLoyaltyEnrollmentDateLocal extends GUPPricingAttributeRetailLoyaltyCard implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailLoyaltyCard, LoyaltyEnrollmentDateLocal);
}

    public Set getAllowedValues()
    {
        RetailLoyaltyCard   retailLoyaltyCard;
        var                 ret = new Set(Types::Date);

        while select LoyaltyEnrollmentDateLocal from retailLoyaltyCard
            group by LoyaltyEnrollmentDateLocal
        {
            ret.add(retailLoyaltyCard.LoyaltyEnrollmentDate);
        }

        return ret;
    }

    protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
    {
        QueryBuildRange qbr;

        qbr = _qbds.addRange(fieldNum(RetailLoyaltyCard, LoyaltyEnrollmentDateLocal));
        qbr.value(queryValue(_value));
    }
